from itertools import permutations
S=[]
for p in permutations('PQRST'):
    d={x:i for i,x in enumerate(p)}  # 0=Mon ... 4=Fri
    if d['Q']>d['R'] and abs(d['P']-d['T'])==2 and d['S'] not in (0,4) and abs(d['R']-d['S'])!=1 and d['S']==2:
        S.append(p)
opts={'A':lambda p:p.index('P')==1,'B':lambda p:p.index('Q')==4,'C':lambda p:p.index('T')==3,'D':lambda p:p.index('P')>p.index('T')}
print(S, [L for L,f in opts.items() if all(f(p) for p in S)])

adj={v:set() for v in 'abcdefg'}
for u,w in 'ab ac bd cd ce df ef fg'.split(): adj[u].add(w); adj[w].add(u)
def is_dfs(s):
    seen={s[0]}; st=[s[0]]
    for v in s[1:]:
        while st and not adj[st[-1]]-seen: st.pop()
        if not st or v in seen or v not in adj[st[-1]]: return False
        seen.add(v); st.append(v)
    return True
print([L for L,s in zip('ABCD',['abdfecg','acbdefg','acdfgbe','acefdbg']) if is_dfs(s)])
